<?php declare(strict_types=1); ?>
<section id="project-releases" class="card files-card release-panel">
<div class="section-heading"><span class="section-icon"><?php icon('upload'); ?></span><div><h2>项目更新包发布</h2><p class="muted">导航站私有源码包：完整上传并校验后，手动发布。</p></div></div>
<?php if (isset($_SESSION['release_token_once'])): ?><div class="error-banner"><p>请立即保存此令牌，仅显示一次。配置在导航站服务器端，不要放入前端代码或下载 URL。</p><input class="token-display" readonly aria-label="导航站访问令牌" value="<?=h($_SESSION['release_token_once'])?>"></div><?php unset($_SESSION['release_token_once']); endif; ?>
<form method="post" enctype="multipart/form-data" class="release-upload"><?php token(); ?><input type="hidden" name="action" value="release_stage"><div class="category-fields"><label>项目<select name="release_project"><option value="hao52okp">hao52okp</option></select></label><label>更新包<input name="package" type="file" accept=".zip" required aria-label="hao52okp-update.zip"></label><label>版本清单<input name="manifest" type="file" accept=".json" required aria-label="update-manifest.json"></label></div><p class="muted">文件名必须为 hao52okp-update.zip 和 update-manifest.json。校验版本、大小、SHA-256 及 ZIP 内版本信息，版本须为 x.y.z。</p><button class="primary">上传并校验</button></form>
<details class="release-access"><summary>私有接口与访问令牌</summary><p class="muted">查询地址：<?=h(rtrim($config['base_url'], '/') . '/api/project-updates/hao52okp/latest')?>。查询、清单和 ZIP 下载都要求 Authorization: Bearer 令牌。</p><p><?= empty($projectReleases['token_hash']) ? '尚未配置令牌，发布按钮不可用。' : '访问令牌已配置。' ?></p><form method="post" class="release-token-form"><?php token(); ?><button name="action" value="release_token" class="secondary"><?= empty($projectReleases['token_hash']) ? '生成访问令牌' : '轮换令牌（旧令牌立即失效）' ?></button><button name="action" value="release_revoke" class="secondary">撤销令牌</button></form></details>
<div class="table-scroll"><table><thead><tr><th>版本</th><th>ZIP 大小</th><th>状态</th><th>更新说明</th><th>操作</th></tr></thead><tbody>
<?php foreach (array_reverse($projectReleases['releases'] ?? [], true) as $release): ?>
<tr><td><?=h($release['version'])?></td><td><?=h(bytesLabel($release['size']))?></td><td><?= $release['status'] === 'draft' ? '已校验，待发布' : (($projectReleases['latest'] ?? '') === $release['id'] ? '当前已发布' : '历史已发布') ?></td><td class="release-notes"><?=h($release['notes'])?></td><td><?php if ($release['status'] === 'draft'): ?><form method="post"><?php token(); ?><input type="hidden" name="release_id" value="<?=h($release['id'])?>"><button class="primary" name="action" value="release_publish"<?= empty($projectReleases['token_hash']) ? ' disabled' : '' ?>>发布</button></form><?php else: ?>已发布<?php endif; ?></td></tr>
<?php endforeach; ?></tbody></table></div>
<?php if (empty($projectReleases['releases'])): ?><p class="muted">尚无更新包。上传未完成或校验失败的文件不会出现在更新查询 API 中。</p><?php endif; ?>
</section>
